// Get query from the "When Executed by Another Workflow" node
// Try to read from trigger node name first
let q;

try {
  q = $('When Executed by Another Workflow').first()?.json?.query;
} catch (e) {
  q = null;
}

// Fallback for tool / sub-workflow calls
if (!q) {
  q = $input.first()?.json?.query;
}

// Normalise text
q = (q || "")
  .toLowerCase()
  .trim()
  .replace(/^["']|["']$/g, "");

// If still no query → return empty
if (!q) {
  return { results: [] };
}

// Split into meaningful words
const words = q
  .replace(/[^\w\s]/g, "") 
  .split(/\s+/)
  .filter(w => w.length > 2);

// Load ALL sheet rows from "Get row(s)" node
const rows = $('Get row(s)').all().map(item => item.json);

// Filter rows where title OR summary contains ANY of the query words
let matches = rows.filter(r => {
  const text = `${r.title||""} ${r.summary||""}`.toLowerCase();
  return words.some(w => text.includes(w));
});


// Return first 10
return { results: matches.slice(0, 2) };
